  sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] = 0
  local activeUnit = sys_info[SysInfo.BATTLE_ACTIVE_UNIT]
  if activeUnit == "" then
    return
  end
  CheckTutorial(activeUnit)
  AutoSaveBattle()
  if g_ActivePlayerUnitFunction ~= nil then
    g_ActivePlayerUnitFunction(activeUnit)
  end
  local LimitTurnEnd = GetLimitTurnEnd()
  local ActivePlayerUnitTurn = -1
  if 0 <= LimitTurnEnd then
    ActivePlayerUnitTurn = GetCurrentLimitTurn()
  end
  if sys_info[SysInfo.BATTLE_STEP_FOR_SERIALIZE_COPY] == 0 then
    OnPreStartActiveUnitCommandSelect()
    if IsSkipTurn() then
      OnSkipTurn(activeUnit)
      sys_info[SysInfo.MOVE_COMMAND_USED] = 1
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
      if 0 <= LimitTurnEnd then
        local CurrnetUnitTurn = GetCurrentLimitTurn() + 1
        if CurrnetUnitTurn ~= ActivePlayerUnitTurn then
          SetBattleTurnCount(LimitTurnEnd - CurrnetUnitTurn)
          if not IsOpen(BATTLE_TURNCOUNT) then
            OpenMenuBattleAll()
          end
          Wait(1.25)
        end
      end
      if g_TurnEndPlayerUnitFunction ~= nil then
        g_TurnEndPlayerUnitFunction(activeUnit)
      end
      OnEndActiveUnitTurn()
      return
    end
    if IsBattleUnitDead(activeUnit) then
      Wait(1)
      IncrementDefeatUnitCountByOccupantType(activeUnit)
      DestroyActor(activeUnit)
      ResetAtBar()
      CheckBattleEndAndWork()
      if g_GameEnd == 0 then
        OnEndActiveUnitTurn()
      end
      return
    end
    SpawnEffect(activeUnit, "Movestart", ACTOR_POSITION_FOOT, 0, 0, 0, 1)
    PlaySE2D("SE_SYS_TURN", activeUnit)
    SoundPlayActionVoiceOnTurnStart(activeUnit)
  end
  SetSysGlobal(SysGlobal.BATTLE_UI_CAN_OPEN_UI_PLAYER, 1)
  RefreshBattleStatusTargetInfo()
  OpenMenuBattleAll()
  local moveAndStandby = false
  local standbyOnly = false
  local lastInputDir = false
  local attackAfterDir = false
  local loop = 1
  
  local function LocalFlagInitFunc()
    print("BattleBase::OnActiveUnitPlayer::LocalFlagInitFunc() (Lua)  Exec.")
    moveAndStandby = false
    standbyOnly = false
    lastInputDir = false
    attackAfterDir = false
    loop = 1
