    local resultMessageFromCPP = CPPFlowManagementResult[_retry(PeekMessage)]
    TSLOG("INPUT_ACTION result", resultMessageFromCPP, l_SelectedAttackInfo and l_SelectedAttackInfo.InfoGopId)
    local attackCommand = GetCurrentAttackCommand()
    if resultMessageFromCPP ~= CPPFlowManagementResult.UNIT_WORK_CANCEL and resultMessageFromCPP ~= CPPFlowManagementResult.MENU_UNIT_DETAIL then
      if attackCommand.InfoGopId == copyAbilityId then
        print("BattleBase::OnActiveUnitPlayer():[INPUT_ACTION]() (Lua)  Detect select ability:[" .. attackCommand.InfoGopId .. "]")
        if IsAssignUnitSelect("FOR_ALL") == false then
          return ExecStatus.INPUT_ACTION
