        l_ActMimicInfo.isApply = true
        local abilityData = CallMimicAbility(activeUnit)
        l_ActMimicInfo.isSuccess = abilityData.IsSuccess
        l_ActMimicInfo.abilityOwnerUnitName = abilityData.AbilityOwnerUnitName
        l_ActMimicInfo.lastUseAbilityName = abilityData.LastUseAbilityName
        print("BattleBase::OnActiveUnitPlayer():[INPUT_ACTION]() (Lua)    Ability copy success ? :[" .. tostring(l_ActMimicInfo.isSuccess) .. "]")
        print("BattleBase::OnActiveUnitPlayer():[INPUT_ACTION]() (Lua)    Ability owner unit-name:[" .. l_ActMimicInfo.abilityOwnerUnitName .. "]")
        print("BattleBase::OnActiveUnitPlayer():[INPUT_ACTION]() (Lua)    Last use ability name:[" .. l_ActMimicInfo.lastUseAbilityName .. "]")
      elseif (attackCommand.InfoGopId == swapDecoyAbilityId or attackCommand.InfoGopId == swapUnitAbilityId) and IsAssignUnitSelectAbility(attackCommand.InfoGopId) == false then
        return ExecStatus.INPUT_ACTION
      end
    end
    if resultMessageFromCPP == CPPFlowManagementResult.NO_OPTIONAL_EFFECT then
      SetLastUseAbilityId(activeUnit)
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
      SetSysGlobal(SysGlobal.BATTLE_STEP_FOR_SERIALIZE, ENUM_CurrentFlowState.ACTION_USED)
      return ExecStatus.EXEC_ACTION
    elseif resultMessageFromCPP == CPPFlowManagementResult.OPTIONAL_EFFECT_ATTACKTARGET_ROTATE then
      if l_SelectedAttackInfo.InfoGopId == "BATTLE_ABILITY_SPRINGBOARD" then
        GhostTrap:Spawn()
      end
      return ExecStatus.INPUT_ROTATE_ATTACKTARGET
    elseif resultMessageFromCPP == CPPFlowManagementResult.MENU_UNIT_DETAIL then
      SetRequestUnitDetailInfo(true)
      if GetRequestUnitDetailInfo() == true then
        OpenBattleUnitDetail()
      else
        print("Unit Detail Opening Failed.")
      end
    elseif resultMessageFromCPP == CPPFlowManagementResult.OPTIONAL_EFFECT_ATTACKTARGET_MOVE then
      return ExecStatus.INPUT_MOVE_ATTACKTARGET
    elseif resultMessageFromCPP == CPPFlowManagementResult.OPTIONAL_EFFECT_SELECT_EXCHANGE_UNIT then
      -- [TSMod] Smuggle v7: a unit command with the exchange, no Quietus mode
      local reason = CanExchangedUnitByAttackTarget()
      if reason ~= 0 then
        BattleOrderCannotSelectExchangedUnitDialog(reason)
        return ExecStatus.INPUT_ACTION
      end
      return ExecStatus.TSMOD_SMUGGLE_SELECT
    elseif resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_CANCEL then
      if l_MenuBackupSelectedAttackInfo ~= nil then
        SetCurrentAttackCommand(sys_info[SysInfo.BATTLE_ACTIVE_UNIT], l_MenuBackupSelectedAttackInfo.Command, l_MenuBackupSelectedAttackInfo.Category, l_MenuBackupSelectedAttackInfo.InfoGopId, l_SelectedAttackInfo.TargetGopId)
      end
      AttachBattleCursorToActiveUnit()
      return ExecStateStack:Pop()
    end
  end
  ExecFunc[ExecStatus.INPUT_ROTATE_ATTACKTARGET] = function()
    if l_SelectedAttackInfo.InfoGopId == "BATTLE_ABILITY_SPRINGBOARD" then
      ChangeAttackTargetRotateTrapMode()
    else
      ChangeAttackTargetRotateMode()
    end
    SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_DIRECTION")
    OpenMenuBattleAll()
    local resultMessageFromCPP = CPPFlowManagementResult[_retry(lambdaWaitCPPFlowManagement)]
    if resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_END then
      return ExecStatus.EXEC_ACTION
    elseif resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_CANCEL then
      GhostTrap:Destroy()
      return ExecStatus.INPUT_ACTION
    end
  end
  ExecFunc[ExecStatus.INPUT_MOVE_ATTACKTARGET] = function()
    ChangeAttackTargetMoveMode()
    SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_LOCATION")
    OpenMenuBattleAll()
    local resultMessageFromCPP = CPPFlowManagementResult[_retry(lambdaWaitCPPFlowManagement)]
    if resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_END then
      return ExecStatus.EXEC_ACTION
    elseif resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_CANCEL then
      return ExecStatus.INPUT_ACTION
    elseif resultMessageFromCPP == CPPFlowManagementResult.MENU_UNIT_DETAIL then
      SetRequestUnitDetailInfo(true)
      if GetRequestUnitDetailInfo() == true then
        OpenBattleUnitDetail()
      else
        print("Unit Detail Opening Failed.")
      end
    end
  end
  ExecFunc[ExecStatus.INPUT_ROTATE] = function()
    _retry(SYS_WaitRefreshDangerArea)
    local noMove = standbyOnly == true
    local waitX = GetBattleCursorMapCoordinate().X
    waitY = GetBattleCursorMapCoordinate().Y
    if DidWaitDirection(noMove, waitX, waitY) == false then
      if lastInputDir == false and standbyOnly == false and attackAfterDir == false then
        return ExecStatus.EXEC_ACTION
      else
        TriggerUnitSeriesTurnEndEvent(activeUnit)
        CheckAndGoInterruptActionByTurnEnd(activeUnit)
        CheckBattleEndAndWork()
        if g_GameEnd ~= 0 then
          return
        end
        standbyOnly = false
        moveAndStandby = false
        loop = 0
        return nil
      end
    end
    if GetActorNameOnMapGrid(waitX, waitY) == nil then
      GhostPlayer:Spwan()
    end
    SetBattleCursorVisibility(false)
    Wait(0.1)
    sys_info[SysInfo.MESSAGE_COMMAND] = ""
    SetBattleCursorVisibility(true)
    local changedFlag = ChangeBattleUnitRotateMode()
    OnStartControlBattleCursor()
    OpenMenuBattleAll()
    local resultMessageFromCPP = CPPFlowManagementResult.UNIT_WORK_CANCEL
    if changedFlag == true then
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_DIRECTION")
      resultMessageFromCPP = CPPFlowManagementResult[_retry(lambdaWaitCPPFlowManagement)]
      SetBattleCursorMoveLock(false)
    end
    if resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_END then
      if lastInputDir == true or attackAfterDir == true then
        SetSelectedDirection(activeUnit)
        SetBattleCursorVisibility(false)
        loop = 0
        TriggerUnitSeriesTurnEndEvent(activeUnit)
        CheckAndGoInterruptActionByTurnEnd(activeUnit)
        CheckBattleEndAndWork()
        if g_GameEnd ~= 0 then
          return
        end
        return nil
      end
      return ExecStatus.EXEC_ACTION
    elseif resultMessageFromCPP == CPPFlowManagementResult.UNIT_WORK_CANCEL then
      if lastInputDir == true then
        if IsBattleUnitDead(activeUnit) then
          CheckBattleEndAndWork()
          return ExecStatus.RESULT_TURN_END
        end
        return nil
      end
      attackAfterDir = false
      if moveAndStandby == true or 0 < sys_info[SysInfo.ATTACK_COMMAND_USED] then
        lamdaMoveCancel()
      end
      standbyOnly = false
      moveAndStandby = false
      return ExecStateStack:Pop()
    end
  end
  ExecFunc[ExecStatus.EXEC_MIGHTY_BLOW] = function()
    local nextState
    SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ACTION")
    OnStartUnitAction()
    AttachBattleCursorToActiveUnit()
    Wait(0.2)
    SetBattleCursorVisibility(false)
    SetActiveUnitPanelVisibility(false)
    if l_SelectedAttackInfo.Command ~= "UNIT_END" then
      ReflectAttackerUnitReservedDirection(activeUnit)
      CloseMenuBattleAll()
      local sequenceIndex = GetBattleSequenceIndex(l_SelectedAttackInfo.AttackParam)
      BeginPlaySequenceForBattle(activeUnit, sequenceIndex, l_SelectedAttackInfo.Category, l_SelectedAttackInfo.InfoGopId)
      ConsumeKP(l_SelectedAttackInfo.InfoGopId)
      AttachBattleCursorToActiveUnit()
      TriggerUnitActionEndEvent(activeUnit)
      UpdateEvaluationInfo()
      CheckBattleEndAndWork()
      ResetAtBar()
      OnCancelClick()
      OnStartControlBattleCursor()
      RefreshBattleStatusTargetInfo()
      OpenMenuBattleAll()
      sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] = 0
    end
    OnActionEndRemainingMoveAction()
    return ExecStatus.INPUT_MOVE
  end
  ExecFunc[ExecStatus.EXEC_SWAP_UNIT] = function()
    local nextState
    SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ACTION")
    OnStartUnitAction()
    CloseMenu(BATTLE_STATUS_TARGET_INFO, "")
    AttachBattleCursorToActiveUnit()
    Wait(0.2)
    SetBattleCursorVisibility(false)
    SetActiveUnitPanelVisibility(false)
    if l_SelectedAttackInfo.Command ~= "UNIT_END" then
      local isExecActionObject = l_SelectedAttackInfo.Command == "UNIT_ACTION_OBJECT" and true or false
      local defenderInfo = GetDefenderInfo()
      ReflectAttackerUnitReservedDirection(activeUnit)
      CloseMenuBattleAll()
      local target = defenderInfo[1]
      local targetUnit = target.Id
      SwapUnitPosition(activeUnit, targetUnit)
      local sequenceIndex = GetBattleSequenceIndex(l_SelectedAttackInfo.AttackParam)
      BeginPlaySequenceForBattle(activeUnit, sequenceIndex, l_SelectedAttackInfo.Category, l_SelectedAttackInfo.InfoGopId)
      AttachBattleCursorToActiveUnit()
      TriggerUnitActionEndEvent(activeUnit)
      UpdateEvaluationInfo()
      CheckBattleEndAndWork()
      ResetAtBar()
      OnCancelClick()
      OnStartControlBattleCursor()
      RefreshBattleStatusTargetInfo()
      OpenMenuBattleAll()
      sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] = 0
    end
    if 0 >= sys_info[SysInfo.MOVE_COMMAND_USED] then
      OnActionEndRemainingMoveAction()
    end
    return ExecStatus.INPUT_MOVE
  end
  ExecFunc[ExecStatus.EXEC_ACTION] = function()
    local nextState
    SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ACTION")
    OnStartUnitAction()
    if standbyOnly then
      SetSelectedDirection(activeUnit)
      SetBattleCursorVisibility(false)
      TriggerUnitSeriesTurnEndEvent(activeUnit)
      CheckAndGoInterruptActionByTurnEnd(activeUnit)
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        return
      end
      if g_PlayerActiveUnitAfterAction ~= nil then
        g_PlayerActiveUnitAfterAction(activeUnit)
      end
      loop = 0
      return
    end
    GhostTrap:Destroy()
    GhostPlayer:Destroy()
    local isIncludeZipLineMove = CheckCameraAdjustAtIncludesZipLineMovement(l_CameraPitchLimitAtZipLineMovement)
    if isIncludeZipLineMove == true then
      local activeUnitPos = GetActorMapGridLocation(activeUnit)
      BattleCameraControl:SetStageCameraAtZipLine(activeUnitPos)
    end
    TriggerActWalkThrough(activeUnit)
    CloseMenu(BATTLE_STATUS_TARGET_INFO, "")
    SetBattleCursorVisibility(false)
    SetActiveUnitPanelVisibility(false)
    local activePos = GetActorMapGridLocation(activeUnit)
    local targetPos = GetReservedMoveTargetCoordinate()
    local outScreenFlag = false
    if DidEnterScreen(activeUnit, 0.1, 0.1) == false then
      AttachBattleCursorToActiveUnit()
      SetNeweraFocusMethod(ACTOR_FOCUS)
      SetNeweraFocusActorName(activeUnit)
      outScreenFlag = true
    end
    BattleCameraControl:SetStageCamera(activePos, targetPos, false, outScreenFlag)
    if ExecUnitMove() and l_SelectedAttackInfo.Command == "UNIT_END" then
      OnStartLastAction()
    end
    WaitActorPathMoving(activeUnit)
    SetNeweraFocusMethod(AUTO_FOCUS)
    EnableCameraLag(false)
    WaitFrame(1)
    AttachBattleCursorToActiveUnit()
    WaitFrame(1)
    EnableCameraLag(true)
    TriggerUnitMoveEndEvent(activeUnit)
    if 0 < sys_info[SysInfo.MOVE_COMMAND_USED] then
      print("BattleBase::OnActiveUnitPlayer() (Lua) ExecFunc[ ExecStatus.EXEC_ACTION ]()  Exec sys_info[ SysInfo.SOMETHING_MOVED ] is [true]")
      sys_info[SysInfo.SOMETHING_MOVED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] = 1
    end
    if 0 < sys_info[SysInfo.IS_MOVE_END_WITH_TRAP] then
      print("trap01")
      print("BattleBase::OnActiveUnitPlayer() (Lua) ExecFunc[ ExecStatus.EXEC_ACTION ]()  Detect [Trap-Activation move stop].  Set [ATTACK_COMMAND_USED] on for turn-end.")
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
      if l_ActTwiceInfo.isApply == true and l_ActTwiceInfo.isActTwiceExec == false then
        print("BattleBase::OnActiveUnitPlayer() (Lua) ExecFunc[ ExecStatus.EXEC_ACTION ]()  Detect [Trap-Activation move stop].  Set [ActTwice] force end.")
        l_ActTwiceInfo.isActTwiceExec = true
      end
      _retry(SYS_WaitActorKnockBackExec)
      CheckSlipDamageAfterAction(activeUnit)
      CheckTrapKnockBackDamageAtGimmick()
    end
    CheckAfterAttackSequenceTrigger()
    CheckBeforeKillEventTrigger()
    local workDeadUnitList = {}
    for key, value in pairs(GetUnitNameListAllIncludeDecoyAndTurret()) do
      if CheckTriggerHPZeroFromSlipDamage(value) == false then
        if IsBattleUnitDead(value) == true and GetUnitCategory(value) == 0 and IsNeedPlayDeathAct(value) == true and CheckHpZero(value) then
          table.insert(workDeadUnitList, value)
        end
      else
        table.insert(workDeadUnitList, value)
      end
    end
    if 0 < #workDeadUnitList then
      Wait(0.9)
      for key, value in pairs(workDeadUnitList) do
        DefaultHPZero(value, nil)
      end
      UpdateBattleDefeatCount()
    end
    if 0 < sys_info[SysInfo.IS_MOVE_END_WITH_TRAP] then
      print("trap02")
      CheckDeadAtLastBoss()
      if IsGameEndAtLastBoss() == 1 then
        loop = 0
        g_GameEnd = 1
        return
      end
      l_SelectedAttackInfo.Command = "UNIT_END"
      CheckAndGoInterruptActionByTurnEnd(activeUnit)
      loop = 0
      return nil
    end
    CheckAndGoInterruptRecovery(activeUnit)
    if CheckAndGoInterruptAction(activeUnit) == true then
      CheckDeadAtLastBoss()
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        l_SelectedAttackInfo.Command = "UNIT_END"
        return
      end
      ResetAtBar()
      if IsBattleUnitDead(activeUnit) then
        l_SelectedAttackInfo.Command = "UNIT_END"
        loop = 0
        return
      end
      if l_SelectedAttackInfo.Command ~= "UNIT_END" then
        lastInputDir = true
        l_SelectedAttackInfo.Command = "UNIT_END"
      end
    end
    if IsBattleUnitDead(activeUnit) then
      print("BattleBase::OnActiveUnitPlayer():[EXEC_ACTION]() (Lua)  Detect move after active-unit:[" .. activeUnit .. "] is [dead].")
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        l_SelectedAttackInfo.Command = "UNIT_END"
        return
      end
      ResetAtBar()
      l_SelectedAttackInfo.Command = "UNIT_END"
      loop = 0
      return
    end
    if moveAndStandby == true then
      SetSelectedDirection(activeUnit)
      loop = 0
      CheckAndGoInterruptActionByTurnEnd(activeUnit)
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        return
      end
      if g_PlayerActiveUnitAfterAction ~= nil then
        g_PlayerActiveUnitAfterAction(activeUnit)
      end
      return
    end
    if l_SelectedAttackInfo.Command ~= "UNIT_END" then
      if 0 < sys_info[SysInfo.MOVE_COMMAND_USED] then
        OnStartLastAction()
      end
      local isExecActionObject = l_SelectedAttackInfo.Command == "UNIT_ACTION_OBJECT" and true or false
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
      l_SelectedAttackInfo.Command = "UNIT_END"
      if l_SelectedAttackInfo.Category == ATK_CAT_ITEM then
        local targetAliveNum = CheckTargetDefendersUnitAlive(activeUnit)
        local isApplicateAction = CheckApplicateAction(activeUnit)
        if targetAliveNum == -1 and isApplicateAction == true or 0 < targetAliveNum or isApplicateAction == true then
          local num = ConsumeItem(activeUnit, l_SelectedAttackInfo.InfoGopId)
        end
      end
      ReflectAttackerUnitReservedDirection(activeUnit)
      local checkDamage = false
      CloseMenuBattleAll()
      if isExecActionObject then
        local TagName = sys_info[SysInfo.MESSAGE_COMMAND_TAGNAME]
        local Argment = sys_info[SysInfo.MESSAGE_COMMAND_ARGMENT]
        print("### Exec ActionObject : " .. TagName .. " " .. Argment)
        StartAction(TagName, Argment)
        print("### Wait ActionObject : " .. TagName)
        _retry(SYS_WaitAction, TagName)
        print("### End ActionObject : " .. TagName)
        AttachBattleCursorToActiveUnit()
        CheckBeforeKillEventTrigger()
        CheckLevelUp(activeUnit)
      else
        local eventAttackInfo = CheckAttackType(true)
        if eventAttackInfo.Type == "Event" then
          EventAttackTrigger(eventAttackInfo)
          AttachBattleCursorToActiveUnit()
        elseif eventAttackInfo.Type == "Instant" then
          local targetAliveNum = CheckTargetDefendersUnitAlive(activeUnit)
          local isApplicateAction = CheckApplicateAction(activeUnit)
          if targetAliveNum == -1 or 0 < targetAliveNum or isApplicateAction == true then
            local sequenceIndex = GetBattleSequenceIndex(l_SelectedAttackInfo.AttackParam)
            BeginPlaySequenceForBattle(activeUnit, sequenceIndex, l_SelectedAttackInfo.Category, l_SelectedAttackInfo.InfoGopId)
            checkDamage = true
            _retry(SYS_WaitTrapActivationEffectExec)
            local isLoopEndTrap = CheckTrapAndSlipAfterAction(activeUnit)
            if isLoopEndTrap == 0 then
              loop = 0
            end
          end
          AttachBattleCursorToActiveUnit()
        else
          if l_SelectedAttackInfo.Category == 1 then
            local sequenceIndex = GetBattleSequenceIndexCT(l_SelectedAttackInfo.AttackParam)
            if sequenceIndex ~= SEQ_LS_END then
              print("BattleBase::OnActiveUnitPlayer:ExecFunc[ EXEC_ACTION ]() (Lua)  Detect <CT Ability>:[" .. l_SelectedAttackInfo.InfoGopId .. "]  select <Sequence>:[" .. sequenceIndex .. "]")
              BeginPlaySequenceCTForBattle(l_SelectedAttackInfo.InfoGopId)
            end
          end
          RegistDelayAbility(activeUnit)
          AttachBattleCursorToActiveUnit()
          sys_info[SysInfo.MOVE_COMMAND_USED] = 1
          sys_info[SysInfo.SOMETHING_MOVED] = 1
          sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] = 1
          sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
          if l_ActTwiceInfo.isApply == true and l_ActTwiceInfo.isActTwiceExec == false then
            l_ActTwiceInfo.isActTwiceExec = true
          end
        end
      end
      if checkDamage == true then
        DamageUnitsTrigger(activeUnit, GetDamageInfo())
        MissUnitsTrigger(activeUnit, GetMissDamageInfo())
      end
      if IsGameEndAtLastBoss() == 1 then
        loop = 0
        g_GameEnd = 1
        return ExecStatus.RESULT_TURN_END
      end
      CheckAndGoInterruptActionByActionEnd(activeUnit)
      if IsGameEndAtLastBoss() == 1 then
        loop = 0
        g_GameEnd = 1
        return ExecStatus.RESULT_TURN_END
      end
      CheckAfterAttackSequenceTrigger()
      TriggerUnitActionEndEvent(activeUnit)
      UpdateEvaluationInfo()
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        return
      end
      ResetAtBar()
      if IsBattleUnitDead(activeUnit) then
        print("Unit dead....")
        loop = 0
        return
      end
      OnCancelClick()
      OnStartControlBattleCursor()
      RefreshBattleStatusTargetInfo()
      OpenMenuBattleAll()
      UpdateBattleDefeatCount()
      sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] = sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] - 1
      if 0 < sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] then
        sys_info[SysInfo.BATTLE_UNIT_SERIES_TURN_ACTED_COUNT] = sys_info[SysInfo.BATTLE_UNIT_SERIES_TURN_ACTED_COUNT] + 1
      end
      if 0 < sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] then
        sys_info[SysInfo.ATTACK_COMMAND_USED] = 0
        sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] = 1
        nextState = ExecStatus.EXEC_MENU
        if 0 < sys_info[SysInfo.MOVE_COMMAND_USED] then
          sys_info[SysInfo.BOOL_BATTLE_COMMAND_NO_CANCEL] = 1
        end
        local isCosumeAction = true
        if l_SelectedAttackInfo.InfoGopId ~= nil and IsActNotConsumeAction(activeUnit, l_SelectedAttackInfo.InfoGopId) == true then
          isConsumeAction = false
        end
        if isCosumeAction == true or isExecActionObject == true then
          ResetTime()
          WaitTime(0.3)
          if l_ActTwiceInfo.isActTwiceExec == false then
            DisplayAbilityEffect(activeUnit, "BATTLE_ABILITY_DOUBLE_ACTION")
          end
          TriggerStartMultiActionStartEvent(activeUnit)
          UpdateEvaluationInfo()
          ClearActiveUnitMoveableInfo()
        end
        SetBattleCursorVisibility(true)
      else
        sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] = 0
      end
      if doubleItemMode == true then
        doubleItemCount = doubleItemCount + 1
        if doubleItemCount == 1 then
          nextState = ExecStatus.EXEC_MENU_ITEM
          ClearActiveUnitMoveableInfo()
          print("\226\152\133\226\152\133\226\152\133 \227\131\128\227\131\150\227\131\171\227\130\162\227\130\164\227\131\134\227\131\160\227\128\128TP\230\182\136\232\178\187 \226\152\133\226\152\133\226\152\133")
          ChangeParamAfterAction(activeUnit, 1, "BATTLE_ABILITY_DOUBLE_ITEM")
        else
        end
      end
      if IsActNotEndAction(activeUnit) and loop ~= 0 then
        local actionStatus = sys_info[SysInfo.MOVE_COMMAND_USED]
        nextState = ExecStatus.EXEC_MENU
        sys_info[SysInfo.ATTACK_COMMAND_USED] = 0
        sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] = l_ActTwiceInfo.tempActionCount
        sys_info[SysInfo.BATTLE_UNIT_SERIES_TURN_ACTED_COUNT] = 0
        ClearActiveUnitMoveableInfo()
        AttachBattleCursorToActiveUnit()
        WorpUnitInitialize()
        sys_info[SysInfo.MOVE_COMMAND_USED] = actionStatus
        sys_info[SysInfo.SOMETHING_MOVED] = actionStatus
        sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] = 0 < sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] and 1 or actionStatus
        SetNoActionFlag(0 < actionStatus)
        SetUsedNotEndAction(activeUnit, true)
        SetBattleCursorVisibility(true)
        ResetCurrentAttackCommand(activeUnit)
      end
      if nextState == nil and 0 < sys_info[SysInfo.MOVE_COMMAND_USED] then
        nextState = ExecStatus.INPUT_ROTATE
        lastInputDir = true
      end
    elseif lastInputDir == true then
      nextState = ExecStatus.INPUT_ROTATE
    else
      SetSelectedDirection(activeUnit)
    end
    if g_PlayerActiveUnitAfterAction ~= nil then
      g_PlayerActiveUnitAfterAction(activeUnit)
    end
    if IsSkipTurn() then
      sys_info[SysInfo.MOVE_COMMAND_USED] = 1
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_MOVED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
      loop = 0
    end
    if 0 < sys_info[SysInfo.MOVE_COMMAND_USED] and nextState == nil then
      loop = 0
    end
    if loop ~= 0 then
      BattleCameraControl:SetTraceCamera(function()
        AttachBattleCursorToActiveUnit()
        Wait(0.5)
      end)
    end
    if l_ActMimicInfo.isUseMimicAbilityExec == true then
      ResetCurrentAttackCommand(activeUnit)
    end
    if l_ActMimicInfo.isApply then
      l_ActMimicInfo.isApply = false
      DisplayMimicAbilityDialog()
    end
    if nextState ~= ExecStatus.EXEC_MENU_ITEM and 0 >= sys_info[SysInfo.MOVE_COMMAND_USED] then
      OnActionEndRemainingMoveAction()
      return ExecStatus.INPUT_MOVE
    end
    if nextState == nil then
      TriggerUnitSeriesTurnEndEvent(activeUnit)
    end
    if loop == 0 then
      CheckAndGoInterruptActionByTurnEnd(activeUnit)
      CheckBattleEndAndWork()
      if g_GameEnd ~= 0 then
        return
      end
    end
    return nextState
  end
  ExecFunc[ExecStatus.EXEC_MENU] = function()
    if sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] > 1 then
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_COMMAND_1")
    elseif sys_info[SysInfo.BATTLE_ABILITY_DOUBLE_ACTION_USING] == 1 and sys_info[SysInfo.BATTLE_UNIT_ACTION_COUNT] > 0 then
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_COMMAND_2")
    else
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_COMMAND")
    end
    OpenMenuBattleAll()
    local menuResult = CPPFlowManagementResult[OpenBattleCommandMenu()]
    if menuResult == CPPFlowManagementResult.UNIT_BATTLE_ORDER then
      lamdaMoveCancel()
      ExecStateStack:Pop()
      return ExecStatus.INPUT_BATTLE_ORDER
    elseif menuResult == CPPFlowManagementResult.MENU_CANCEL then
      lamdaMoveCancel()
      return ExecStateStack:Pop()
    elseif menuResult == CPPFlowManagementResult.UNIT_STANDBY then
      if 0 >= sys_info[SysInfo.MOVE_COMMAND_USED] then
        standbyOnly = true
      end
      ExecStateStack:Push(ExecStatus.EXEC_MENU)
      AttachBattleCursorToActiveUnit()
      SetBattleCursorMoveLock(false)
      return ExecStatus.INPUT_ROTATE
    elseif menuResult == CPPFlowManagementResult.UNIT_ACTION_OBJECT then
      return ExecStatus.EXEC_ACTION
    end
    if l_SelectedAttackInfo.Command == "UNIT_ATTACK" and l_SelectedAttackInfo.Category == 1 and l_SelectedAttackInfo.InfoGopId == "BATTLE_ABILITY_DOUBLE_ITEM" then
      doubleItemMode = true
      doubleItemCount = 0
      return ExecStatus.EXEC_MENU_ITEM
    end
    ExecStateStack:Push(ExecStatus.EXEC_MENU)
    return ExecStatus.INPUT_ACTION
  end
  ExecFunc[ExecStatus.EXEC_MENU_ITEM] = function()
    OnStartControlBattleCursor()
    SetBattleCursorVisibility(true)
    SetDoubleItemCommandMenu(doubleItemCount)
    if doubleItemMode == true and doubleItemCount == 0 then
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ITEM_1")
    elseif doubleItemMode == true and doubleItemCount == 1 then
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ITEM_2")
    else
      SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_COMMAND")
    end
    OpenMenuBattleAll()
    local menuResult = CPPFlowManagementResult[OpenBattleCommandMenu()]
    EndDoubleItemCommandMenu()
    if menuResult == CPPFlowManagementResult.MENU_CANCEL then
      if doubleItemCount == 0 then
        doubleItemMode = false
        return ExecStatus.EXEC_MENU
      else
        menuResult = OutputCommandEnd()
        if menuResult == 0 then
          l_SelectedAttackInfo.Command = "UNIT_END"
          l_SelectedAttackInfo.Category = ""
          doubleItemMode = false
          doubleItemCount = 0
          if 0 >= sys_info[SysInfo.MOVE_COMMAND_USED] then
            return ExecStatus.INPUT_MOVE
          else
            sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
            sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
            standbyOnly = true
            lastInputDir = true
            AttachBattleCursorToActiveUnit()
            SetBattleCursorMoveLock(false)
            return ExecStatus.INPUT_ROTATE
          end
        else
          return ExecStatus.EXEC_MENU_ITEM
        end
      end
    elseif menuResult == CPPFlowManagementResult.UNIT_STANDBY then
      ExecStateStack:Push(ExecStatus.EXEC_MENU_ITEM)
      if 0 >= sys_info[SysInfo.MOVE_COMMAND_USED] then
        standbyOnly = true
      end
      AttachBattleCursorToActiveUnit()
      SetBattleCursorMoveLock(false)
      return ExecStatus.INPUT_ROTATE
    end
    ExecStateStack:Push(ExecStatus.EXEC_MENU_ITEM)
    return ExecStatus.INPUT_ACTION
  end
  ExecFunc[ExecStatus.INPUT_BATTLE_ORDER] = function()
    OpenMenuBattleAll()
    local resultMessageFromCPP = OnBattleOrder()
    if resultMessageFromCPP ~= nil and IsBattleOrderGopId(resultMessageFromCPP) == true then
      resultMessageFromCPP_EXEC_BATTLE_ORDER = resultMessageFromCPP
      return ExecStatus.EXEC_BATTLE_ORDER
    end
    return ExecStatus.INPUT_MOVE
  end
  ExecFunc[ExecStatus.EXEC_BATTLE_ORDER] = function()
    local battleOrderTable = GetGopBattleOrder(resultMessageFromCPP_EXEC_BATTLE_ORDER)
    if battleOrderTable.SelfId == resultMessageFromCPP_EXEC_BATTLE_ORDER then
      print("### \229\136\135\227\130\138\230\156\173")
      print("SelfId " .. battleOrderTable.SelfId)
      print("BattleOrderName " .. battleOrderTable.BattleOrderName)
      print("BattleOrderHelp " .. battleOrderTable.BattleOrderHelp)
      print("AttackParam " .. battleOrderTable.AttackParam)
      print("eFunctionIconType " .. tostring(battleOrderTable.eFunctionIconType))
      print("eTargetCategory " .. tostring(battleOrderTable.eTargetCategory))
      print("iConsumePoint " .. tostring(battleOrderTable.iConsumePoint))
      l_SelectedAttackInfo.Category = 4
      l_SelectedAttackInfo.InfoGopId = battleOrderTable.SelfId
      ChangeTrumpMode(resultMessageFromCPP_EXEC_BATTLE_ORDER)
      if "BATTLE_ORDER_TEST_RESURRECTION" == battleOrderTable.SelfId or "BATTLE_ORDER_TEST_REBORN" == battleOrderTable.SelfId then
        ClearCellInfo()
        return ExecStatus.INPUT_SELECT_UNIT
      end
      if "BATTLE_ORDER_TEST_CHANGE" == battleOrderTable.SelfId then
        SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_MEMBER_CHANGE_LEAVE")
      else
        SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_TARGET")
      end
      SetUnitTrampSelect(activeUnit, true)
      local workResultId = CPPFlowManagementResult[_retry(PeekMessage)]
      SetUnitTrampSelect(activeUnit, false)
      if workResultId == CPPFlowManagementResult.UNIT_WORK_CANCEL then
        return ExecStatus.INPUT_BATTLE_ORDER
      end
      if workResultId == CPPFlowManagementResult.NO_OPTIONAL_EFFECT then
        if "BATTLE_ORDER_TEST_MIGHTY_BLOW" == battleOrderTable.SelfId then
          return ExecStatus.EXEC_MIGHTY_BLOW
        end
        OnStartUnitAction()
        CloseMenuBattleAll()
        SetBattleCursorVisibility(false)
        SetActiveUnitPanelVisibility(false)
        SetCommonButtonGuideId("COMMON_BTNGUIDE_BATTLE_ACTION")
        BeginPlaySequenceForBattle(activeUnit, GetBattleSequenceIndex(l_SelectedAttackInfo.AttackParam), l_SelectedAttackInfo.Category, l_SelectedAttackInfo.InfoGopId)
        ConsumeKP(l_SelectedAttackInfo.InfoGopId)
        AttachBattleCursorToActiveUnit()
        OnCancelClick()
        OnStartControlBattleCursor()
        RefreshBattleStatusTargetInfo()
        OpenMenuBattleAll()
      elseif workResultId == CPPFlowManagementResult.OPTIONAL_EFFECT_ATTACKTARGET_MOVE then
        SetActiveUnitPanelVisibility(false)
        return ExecStatus.INPUT_MOVE_FRINDTARGET
      elseif workResultId == CPPFlowManagementResult.OPTIONAL_EFFECT_SELECT_EXCHANGE_UNIT then
        -- [TSMod] Hidden Reserves: summoned units (no party record) can't be swapped out
        local tsmod_hr_found, tsmod_hr_tgt = pcall(function() return TSMOD_UnitAt(GetAttackTargetCoordinate()) end)
        if tsmod_hr_found and tsmod_hr_tgt ~= nil then
          local tsmod_hr_ok, tsmod_hr_party = pcall(function() return IsPartyIn(GetUnitGopId(tsmod_hr_tgt)) == true end)
          if tsmod_hr_ok and tsmod_hr_party ~= true then
            TSLOG("smuggle: hidden reserves refused, not a party member", tsmod_hr_tgt)
            BattleOrderCannotSelectExchangedUnitDialog(1)
            return ExecStatus.EXEC_BATTLE_ORDER
          end
        end
        local reason = CanExchangedUnitByAttackTarget()
        if reason ~= 0 then
          BattleOrderCannotSelectExchangedUnitDialog(reason)
          return ExecStatus.EXEC_BATTLE_ORDER
        end
        return ExecStatus.INPUT_SELECT_EXCHANGE_UNIT
      elseif workResultId == CPPFlowManagementResult.MENU_UNIT_DETAIL then
        SetRequestUnitDetailInfo(true)
        local returnMode = ExecStatus.EXEC_BATTLE_ORDER
        if GetRequestUnitDetailInfo() == true then
          local isExchangeUnit = false
          if battleOrderTable.SelfId == "BATTLE_ORDER_TEST_CHANGE" then
            print("+++++ Unit Detail Open Exchange Unit Mode.")
            isExchangeUnit = true
          end
          if isExchangeUnit == true then
            SetMainMenuUnitListActionModeExchangeUnitSelect()
          end
          OpenBattleUnitDetail()
          if isExchangeUnit == true then
            local selectUnitId = GetMainMenuUnitListSelectUnitId()
            if selectUnitId ~= "" then
              print("UnitDetail return : Slecte Exchange Unit Id = " .. selectUnitId)
              SetExchangedUnit(selectUnitId)
              returnMode = ExecStatus.INPUT_SELECT_EXCHANGE_UNIT
            end
          end
          ResetMainMenuUnitListActionMode()
        end
        return returnMode
      elseif workResultId == CPPFlowManagementResult.UNIT_WORK_CANCEL then
        AttachBattleCursorToActiveUnit()
      end
      OnActionEndRemainingMoveAction()
      return ExecStatus.INPUT_MOVE
    end
  end
  ExecStateStack:Clear()
  local execStatus = ExecStatus.INPUT_MOVE
  SetSysGlobal(SysGlobal.BATTLE_STEP_FOR_SERIALIZE, ENUM_CurrentFlowState.COMMAND_START)
  InitActTwiceInfo(activeUnit)
  if sys_info[SysInfo.BATTLE_STEP_FOR_SERIALIZE_COPY] == 11 then
    if l_ActTwiceInfo.isActTwiceExec == false then
      sys_info[SysInfo.ATTACK_COMMAND_USED] = 1
      sys_info[SysInfo.BATTLE_UNIT_TURN_ACTED] = 1
    end
    l_SelectedAttackInfo.Command = "UNIT_END"
    if 0 < sys_info[SysInfo.BATTLE_UNIT_MOVE_COUNT] then
      sys_info[SysInfo.BATTLE_STEP_FOR_SERIALIZE_COPY] = 0
    end
  end
  SetNoActionFlag(false)
  InitMimicInfo()
  if l_ActTwiceInfo.isApply == true and l_ActTwiceInfo.isActTwiceExec == true then
    AttachBattleCursorToActiveUnit()
  end
  while execStatus ~= nil and execStatus ~= ExecStatus.RESULT_TURN_END and loop ~= 0 do
    local tmpInputMode
    if execStatus == ExecStatus.EXEC_ACTION then
      tmpInputMode = SetActionInputMode(INPUT_MODE_ON_STAGE)
    end
    TSLOG("state ->", TSMOD_StateName(execStatus), activeUnit)
    local nextExecStatus = ExecFunc[execStatus]()
    if tmpInputMode ~= nil then
      SetActionInputMode(tmpInputMode)
    end
    if g_GameEnd ~= 0 then
      return
    end
    if nextExecStatus ~= nil then
      execStatus = nextExecStatus
    end
    if loop == 0 and l_ActTwiceInfo.isApply == true and l_ActTwiceInfo.isActTwiceExec == false and IsStatusEffectTriggered(activeUnit, EStatusEffectACT_TWICE) then
      print("BattleBase::OnActiveUnitPlayer() (Lua) : Detect ability [Act-Twice] Execute !")
      InitSysInfoBattleWithActTwice()
      l_ActTwiceInfo.isActTwiceExec = true
      SetUsedNotEndAction(activeUnit, false)
      ClearActiveUnitMoveableInfo()
      WorpUnitInitialize()
      AttachBattleCursorToActiveUnit()
      execStatus = ExecStatus.INPUT_MOVE
      LocalFlagInitFunc()
      TriggerActTwiceExecEvent(activeUnit)
      print("BattleBase::OnActiveUnitPlayer() (Lua) : ActTwiceInfo  [isActTwiceExec]:" .. tostring(l_ActTwiceInfo.isActTwiceExec))
      print("BattleBase::OnActiveUnitPlayer() (Lua) : moveAndStandby:" .. tostring(moveAndStandby) .. "  standbyOnly:" .. tostring(standbyOnly) .. "  loop:" .. loop)
      BattleCameraControl:Init()
    end
  end
  if execStatus == ExecStatus.RESULT_TURN_END then
    ResetTime()
    if GetReplaceUnit() == activeUnit then
      WaitTime(1)
    end
    CheckNextActiveUnit(0.2)
    return
  end
  if 0 <= LimitTurnEnd then
    local CurrnetUnitTurn = GetCurrentLimitTurn() + 1
    if CurrnetUnitTurn ~= ActivePlayerUnitTurn then
      SetBattleTurnCount(LimitTurnEnd - CurrnetUnitTurn)
      Wait(1.25)
    end
  end
  if g_TurnEndPlayerUnitFunction ~= nil then
    g_TurnEndPlayerUnitFunction(activeUnit)
  end
  OnEndActiveUnitTurn()
  g_KeepBattleCameraPlayerDistance = GetSpringArmDistanceByActiveCamera()
  g_KeepBattleCameraPlayerRotation = GetCameraRotationByActiveCamera()
  if sys_info[SysInfo.BATTLE_STEP_FOR_SERIALIZE_COPY] ~= 0 then
    sys_info[SysInfo.BATTLE_STEP_FOR_SERIALIZE_COPY] = 0
  end
  SetSysGlobal(SysGlobal.BATTLE_UI_CAN_OPEN_UI_PLAYER, 0)
  SetCommonButtonGuideId("COMMON_BTNGUIDE_EMPTY")
end
